import pyomo.environ as pyo

DATA = {
    "foods": ["Lentils", "Rice", "Chicken", "Beef", "Tofu"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Lentils": 7,
        "Rice": 6,
        "Chicken": 6,
        "Beef": 10,
        "Tofu": 2,
    },
    "content": {
        # nutrient: {food: amount}
        "protein": {"Lentils": 13, "Rice": 2, "Chicken": 7, "Beef": 18, "Tofu": 12},
        "carbs": {"Lentils": 21, "Rice": 30, "Chicken": 13, "Beef": 8, "Tofu": 28},
        "calories": {"Lentils": 284, "Rice": 55, "Chicken": 276, "Beef": 204, "Tofu": 160},
    },
    "requirement": {"protein": 79, "carbs": 170, "calories": 1699},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    # x[i]: quantity/amount of food i purchased (continuous, nonnegative)
    model.x = pyo.Var(model.I, within=pyo.NonNegativeReals, bounds=(0, None))

    def cost_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.I)

    model.obj = pyo.Objective(expr=cost_rule, sense=pyo.minimize)

    # Each nutrient requirement must be met: sum_i content * x_i >= requirement
    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.x[i] for i in m.I) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.N, rule=nutrient_rule)

    return model


